using System.Numerics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        int i = 0;

        if (Vector.IsHardwareAccelerated && values.Length >= Vector<float>.Count * 2)
        {
            ref float start = ref MemoryMarshal.GetReference(values);
            var acc0 = Vector<float>.One;
            var acc1 = Vector<float>.One;
            int vecCount = Vector<float>.Count;
            int limit = values.Length - vecCount * 2 + 1;

            // Two-accumulator loop to hide multiply latency
            for (; i < limit; i += vecCount * 2)
            {
                acc0 *= new Vector<float>(values.Slice(i, vecCount));
                acc1 *= new Vector<float>(values.Slice(i + vecCount, vecCount));
            }

            acc0 *= acc1;

            // Horizontal reduction across vector lanes
            float product = 1f;
            for (int lane = 0; lane < vecCount; lane++)
                product *= acc0[lane];

            // Scalar tail
            for (; i < values.Length; i++)
                product *= values[i];

            return product;
        }

        // Scalar fallback with 4-way unroll
        float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
        int scalarLimit = values.Length - 3;
        for (; i < scalarLimit; i += 4)
        {
            p0 *= values[i];
            p1 *= values[i + 1];
            p2 *= values[i + 2];
            p3 *= values[i + 3];
        }
        float result = p0 * p1 * p2 * p3;
        for (; i < values.Length; i++)
            result *= values[i];
        return result;
    }
}

